    const repair=r.repair||{};
    const repairGroup=(title,items,tone)=>items?.length?`<article class="${tone}"><b>${E(title)}</b><ul>${items.map(x=>`<li>${E(x)}</li>`).join("")}</ul></article>`:"";
    const openObs=(m?.objections||[]).filter(o=>o.d!=="RESOLVED");
    const disp=(d)=>({EXISTING_EVIDENCE_ACTIONABLE:isZh()?"现有证据可补":"Existing evidence",REQUIRES_SCIENTIFIC_REOPEN:isZh()?"需重开科学实验":"Scientific reopen",PERMANENT_CLAIM_BOUNDARY:isZh()?"永久边界":"Permanent boundary",RESOLVED:isZh()?"已解决":"Resolved"}[d]||d);
    return `<section class="panel cpp-e1-review" id="external-review-summary"><div class="cpp-section-kicker">${isZh()?"外部审稿怎么看":"EXTERNAL REVIEW"}</div><div class="cpp-e1-review-head"><div><h3>${isZh()?"把 reviewer 当成压力测试：它认可什么，还不信什么？":"Use the reviewer as a pressure test: what is convincing and what is not?"}</h3><p>${E(T(r.reviewer_take))}</p></div><div class="cpp-e1-review-score"><span>${isZh()?"Round 2 外部建议":"ROUND 2"}</span><strong>${E(String(r.score))}</strong><b>${E(T(r.recommendation))}</b><small>${isZh()?`Round 1：${r.prior_score} · ${T(r.prior_recommendation)}`:`Round 1: ${r.prior_score} · ${T(r.prior_recommendation)}`}</small></div></div><div class="cpp-e1-review-columns"><article class="positive"><b>${isZh()?"Reviewer 为什么愿意接收":"Why the reviewer buys the paper"}</b><ul>${strengths.map(x=>`<li>${E(x)}</li>`).join("")}</ul></article><article class="pressure"><b>${isZh()?"仍然最容易被攻击的地方":"Remaining pressure points"}</b><ul>${concerns.map(x=>`<li>${E(x)}</li>`).join("")}</ul></article></div><div class="cpp-e1-repair"><header><b>${isZh()?"Targeted Repair：哪些该修，哪些不应该为了分数重开主线？":"Targeted repair: what to fix without reopening the scientific story"}</b><p>${isZh()?"Round 2 已给 Accept，因此这里的目的不是追更高分，而是把可离线修复的问题补好、把真正的新科学问题明确留在边界外。":"Round 2 already recommends acceptance; repairs should close cheap evidence gaps without reopening new scientific objects."}</p></header><div>${repairGroup(isZh()?"论文表达":"Manuscript",repair.manuscript?.[isZh()?"zh":"en"]||repair.manuscript?.zh,"manuscript")}${repairGroup(isZh()?"零调用 / 离线分析":"Offline analysis",repair.analysis?.[isZh()?"zh":"en"]||repair.analysis?.zh,"analysis")}${repairGroup(isZh()?"新增行为实验":"New behavioral experiment",repair.experiment?.[isZh()?"zh":"en"]||repair.experiment?.zh,"experiment")}</div></div>${openObs.length?`<details class="cpp-e1-review-history"><summary><div><b>${isZh()?"展开历次 objection 与当前 disposition":"Open objection history and current dispositions"}</b><span>${isZh()?"默认只看最新判断；这里保留 Round 1→Round 2 以及每条 objection 为什么 resolved / boundary / reopen。":"The default view shows the current judgment; this preserves the full objection trail."}</span></div><em>${isZh()?"审稿历史":"HISTORY"}</em></summary><div><div class="cpp-e1-review-timeline"><span><b>Round 1</b>${r.prior_score} · ${E(T(r.prior_recommendation))}</span><i>→</i><span><b>Round 2</b>${r.score} · ${E(T(r.recommendation))}</span></div>${(m?.objections||[]).map(o=>`<article><header><b>${E(T(o.topic))}</b><span class="${String(o.d||"").toLowerCase()}">${E(disp(o.d))}</span></header><p>${E(T(o.why))}</p></article>`).join("")}</div></details>`:""}<small class="cpp-e1-review-disclaimer">${isZh()?"说明：这是外部 reviewer 的只读建议，不是官方 ICLR 分数或录用结果，也不授予新的实验权限。":"Advisory external review only; not an official ICLR score or acceptance decision and grants no experimental authority."}</small></section>`;
