    return `<div class="cpp-gap-literature"><div class="cpp-gap-literature-head"><b>${isZh()?"代表工作 · 会议 / 年份":"Representative work · venue / year"}</b><span>${isZh()?"正式发表显示 venue；未正式发表保留 arXiv。":"Published work shows its venue; preprints remain arXiv."}</span></div><div class="cpp-gap-literature-grid">${groups.map(g=>`<article><strong>${E(P(plainUiLabel(g.name)))}</strong>${g.works.map(w=>`<a href="${E(w.url||w.u||"#")}" target="_blank" rel="noopener"><span>${E(w.title||w.t||"")}</span>${venueYearTag(w)?`<em class="cpp-venue-tag">${E(venueYearTag(w))}</em>`:""}</a>`).join("")}</article>`).join("")}</div></div>`;
