  const beginnerContributions=(pageId,spec,detail)=>`<section class="panel cpp-e1-contributions cpp-beginner-contributions" id="claim-boundary"><div class="cpp-section-kicker">${isZh()?"5 · 最终贡献与边界":"5 · CONTRIBUTIONS & BOUNDARIES"}</div><h3 class="cpp-subsection-title">${isZh()?"所以这篇论文 / 科学对象真正让我们多知道了什么？":"What do we know because of this paper or scientific object?"}</h3><div class="cpp-contribution-grid">${spec.contributions.map(x=>`<article><span>${E(x[0])}</span><div><b>${E(plainNarrative(pageId,x[1]))}</b><p>${E(plainNarrative(pageId,x[2]))}</p></div></article>`).join("")}</div>${detail?.interpretation?.importance?`<div class="cpp-contribution-why"><b>${isZh()?"为什么读者应该在意这件事":"Why this matters beyond this one experiment"}</b><p>${E(plainNarrative(pageId,T(detail.interpretation.importance)))}</p></div>`:""}<div class="cpp-boundary-box"><b>${isZh()?"同样重要：现在明确不能写成什么":"Equally important: what cannot currently be claimed"}</b>${list(spec.limits.map(x=>({zh:plainNarrative(pageId,x),en:x})),"boundary")}</div></section>`;
  const beginnerStatus=(pageId,paper,reg,spec)=>`<section class="panel cpp-next cpp-e1-status cpp-beginner-status" id="next-gate"><div class="cpp-section-kicker">${isZh()?"7 · 当前状态与下一步":"7 · CURRENT STATE & NEXT"}</div><h3 class="cpp-subsection-title">${E(plainNarrative(pageId,spec.statusHeadline))}</h3>${statePrimer(paper,reg)}<div class="cpp-e1-state-grid">${spec.statusCards.map((x,i)=>`<article class="${i?"hold":""}"><span>${E(plainNarrative(pageId,x[0]))}</span><strong>${E(x[1])}</strong><p>${E(plainNarrative(pageId,x[2]))}</p></article>`).join("")}</div><div class="cpp-next-action"><b>${isZh()?"下一步用一句话说":"Next, in plain language"}</b><p>${E(plainNarrative(pageId,spec.nextPlain))}</p></div>${registryBox(paper,reg)}</section>`;
